/**
 * Consumption-`Package.swift` generation. The `render*` functions are PURE
 * (inputs → manifest string) so the generated bytes are unit-testable; the
 * `emit*` functions are thin wrappers that add the filesystem side effects
 * (mkdir, `root` symlink, write) and return the RN dependency contributions.
 */

'use strict';

const fs = require('fs');
const path = require('path');
const { collectIgnoredDirs } = require('./classify');
const { reactProductDependencies, reactPackageDeclarations } = require('./react-descriptor');
const { runDumpPackage } = require('./cli');

// ---------------------------------------------------------------------------
// Pure: parse `swift package dump-package` JSON → { name, products, targets }
// ---------------------------------------------------------------------------

/**
 * A same-package target dependency: the bare target name, or `{ name, platforms }`
 * when the manifest conditions it.
 */
function siblingDependency(dep) {
  const [name, condition] = dep.byName ?? dep.target ?? [];
  if (name == null) return null;
  const platforms = condition?.platformNames ?? [];
  return platforms.length ? { name, platforms } : name;
}

const siblingName = (dep) => (typeof dep === 'string' ? dep : dep.name);

/**
 * The version a dumped source-control dependency is pinned at, or null when it names
 * no form the generated package can declare. `.package(url:from:)` arrives here as a
 * range — `dump-package` has already widened it — so there is no `from:` form to read.
 */
function packageRequirement(requirement) {
  const [form, values] = Object.entries(requirement ?? {})[0] ?? [];
  if (form === 'range') {
    const { lowerBound, upperBound } = values?.[0] ?? {};
    return lowerBound != null && upperBound != null
      ? { kind: 'range', lowerBound, upperBound }
      : null;
  }
  if (form === 'exact' || form === 'branch' || form === 'revision') {
    return typeof values?.[0] === 'string' ? { kind: form, value: values[0] } : null;
  }
  return null;
}

/** Whether a trait set is anything but the default one every dumped dependency carries. */
function hasNonDefaultTraits(traits) {
  if (traits == null) return false;
  return traits.length !== 1 || traits[0]?.name !== 'default';
}

/**
 * The packages the generated manifest mirrors, keyed by every name a target dependency
 * may resolve them by, plus one entry per package it cannot declare. A dropped package
 * is invisible until the module's first `import` of it, so every form this cannot
 * render is collected rather than skipped.
 */
function parsePackageDependencies(dependencies, injectedNames) {
  const packageDeps = [];
  // SwiftPM resolves a `.product(package:)` against the package's identity or against
  // the name a deprecated `.package(name:url:)` gave it, case-insensitively.
  const packagesByName = new Map();
  const unsupported = [];
  // The reported package behind each name, so a target dependency on one is attributed
  // to the fault that already explains it instead of being reported a second time.
  const reportedByName = new Map();
  const report = (form, identity, ...otherNames) => {
    const entry = { form, identity: identity ?? null, target: null };
    unsupported.push(entry);
    // A dependency resolves a package by its identity OR by the name a `.package(name:)`
    // gave it, so a rejected package must answer to both — otherwise a product naming it
    // looks undeclared, and the reader is sent to add a declaration already in front of them.
    for (const name of [identity, ...otherNames]) {
      if (typeof name !== 'string' || reportedByName.has(name.toLowerCase())) continue;
      reportedByName.set(name.toLowerCase(), entry);
    }
  };
  for (const dependency of dependencies ?? []) {
    const [form, declarations] = Object.entries(dependency ?? {})[0] ?? [];
    const declared = declarations?.[0] ?? {};
    if (form === 'sourceControl') {
      const url = declared.location?.remote?.[0]?.urlString;
      const requirement = url != null ? packageRequirement(declared.requirement) : null;
      if (url == null) {
        report(
          'unsupported-location',
          declared.identity,
          declared.nameForTargetDependencyResolutionOnly
        );
      } else if (requirement == null) {
        report(
          'unsupported-requirement',
          declared.identity,
          declared.nameForTargetDependencyResolutionOnly
        );
      } else {
        // Traits select which of a package's code builds, and this renders none of them,
        // so a non-default set would build something other than the module declared.
        if (hasNonDefaultTraits(declared.traits)) report('unsupported-traits', declared.identity);
        const pkg = { identity: declared.identity ?? null, url, requirement };
        packageDeps.push(pkg);
        for (const name of [declared.identity, declared.nameForTargetDependencyResolutionOnly]) {
          if (typeof name !== 'string') continue;
          // Two packages answering to one name would resolve to whichever was declared
          // last — a silent choice between two different dependencies.
          if ((packagesByName.get(name.toLowerCase()) ?? pkg) !== pkg) {
            report('ambiguous-package-name', name);
          }
          packagesByName.set(name.toLowerCase(), pkg);
        }
      }
    } else if (form === 'fileSystem') {
      // Mirroring one would mean rewriting its path against the `root` symlink, which
      // this plugin does not do.
      report('local-path', declared.identity, declared.nameForTargetDependencyResolutionOnly);
    } else if (form === 'registry') {
      report('registry', declared.identity, declared.nameForTargetDependencyResolutionOnly);
    } else {
      report('unknown-form', declared.identity, declared.nameForTargetDependencyResolutionOnly);
    }
  }
  // SwiftPM refuses a graph where two packages resolve to one identity, so a mirrored
  // package may not take a name the injected declarations already occupy.
  const injected = new Set(injectedNames.map((name) => name.toLowerCase()));
  for (const { identity } of packageDeps) {
    if (identity != null && injected.has(identity.toLowerCase())) {
      report('collides-with-injected', identity);
    }
  }
  return { packageDeps, packagesByName, reportedByName, unsupportedPackageDeps: unsupported };
}

/**
 * The package identities the injected declarations already occupy: RN's package ref
 * plus every package its products come from. Mirrors `reactPackageDeclarations` in
 * react-descriptor.js, which is where those declarations are rendered. A path package
 * answers to two names — SwiftPM takes its identity from the directory, while target
 * dependencies name it by its `name:` — and both are occupied.
 */
function injectedPackageNames(react) {
  if (react == null) return [];
  const ref = react.packageRef;
  return [
    ref.name,
    ref.url != null ? spmPackageIdentity(ref) : null,
    ref.path != null ? path.basename(ref.path) : null,
    ...react.products.map((p) => p.package),
  ].filter((name) => typeof name === 'string');
}

const hasEntries = (value) => value != null && Object.keys(value).length > 0;

/**
 * Whether a target-dependency condition sets anything this renderer does not carry.
 * Swift tools 6.1 added traits to it, and a condition rendered without them would
 * apply the dependency more widely than the module declared.
 */
function unrenderableCondition(condition) {
  return Object.entries(condition ?? {}).some(
    ([key, value]) =>
      key !== 'platformNames' && value != null && (!Array.isArray(value) || value.length > 0)
  );
}

/** Why a `.product` dependency cannot be mirrored, or null when it can. */
function productFault(declaredPackage, moduleAliases, condition) {
  if (declaredPackage == null) return 'undeclared-package';
  // An alias renames a dependency's modules. Rendering the dependency without it would
  // leave the module importing a name nothing declares, or reintroduce the duplicate
  // module name the alias exists to resolve.
  if (hasEntries(moduleAliases)) return 'module-aliases';
  if (unrenderableCondition(condition)) return 'unsupported-condition';
  return null;
}

/**
 * The name a mirrored `.product` must give its package. The mirrored declaration carries
 * no `name:`, so a dependency that named the package by a deprecated `.package(name:)`
 * has to name the identity instead; a name that differs only in case resolves as written.
 */
function resolvablePackageName(written, declaredPackage) {
  const { identity } = declaredPackage;
  return identity != null && identity.toLowerCase() !== written.toLowerCase() ? identity : written;
}

/**
 * Keep only regular targets and library products; resolve each target's dependencies
 * against the targets and packages this package declares, in their declared order, and
 * collect everything the generated package cannot re-declare.
 */
function parseDumpedManifest(json, injectedNames = []) {
  const pkg = JSON.parse(json);
  const { packageDeps, packagesByName, reportedByName, unsupportedPackageDeps } =
    parsePackageDependencies(pkg.dependencies, injectedNames);
  const declaredTargets = pkg.targets ?? [];
  const declaredKinds = new Map(declaredTargets.map((t) => [t.name, t.type]));
  const regular = declaredTargets.filter((t) => t.type === 'regular');
  const regularNames = new Set(regular.map((t) => t.name));
  const unsupportedTargetDeps = [];
  // The PRODUCT names the mirrored targets take from those packages. Dependency
  // diagnostics match a pod name against these — `libavif/libdav1d` is covered by the
  // `libavif` product, whatever the package it ships in is called.
  const spmProductNames = [];

  const targets = regular.map((t) => {
    const dependencies = [];
    for (const dep of t.dependencies ?? []) {
      if (dep.product != null) {
        const [name, packageName, moduleAliases, condition] = dep.product;
        const declaredPackage =
          packageName != null ? (packagesByName.get(packageName.toLowerCase()) ?? null) : null;
        // A dependency this cannot mirror faithfully is reported, never dropped: dropped,
        // it compiles until the module's first import of it.
        const fault = productFault(declaredPackage, moduleAliases, condition);
        if (fault != null) {
          // A package left out of the name map because it was already reported IS
          // declared: calling it undeclared as well would contradict the line that
          // explains it. That line takes the target instead, so nothing is lost.
          const reported = reportedByName.get((packageName ?? '').toLowerCase());
          if (fault === 'undeclared-package' && reported != null) reported.target ??= t.name;
          else {
            unsupportedPackageDeps.push({
              form: fault,
              identity: packageName ?? null,
              target: t.name,
            });
          }
          continue;
        }
        dependencies.push({
          product: name,
          package: resolvablePackageName(packageName, declaredPackage),
          platforms: condition?.platformNames ?? [],
        });
        spmProductNames.push(name);
        continue;
      }
      const sibling = siblingDependency(dep);
      if (sibling == null) continue;
      const name = siblingName(sibling);
      if (unrenderableCondition((dep.byName ?? dep.target)[1])) {
        unsupportedPackageDeps.push({
          form: 'unsupported-target-condition',
          identity: name,
          target: t.name,
        });
      } else if (regularNames.has(name)) {
        dependencies.push(sibling);
      } else if (declaredKinds.has(name)) {
        // Only regular targets are mirrored, so a dependency on a target of any other
        // kind names a target the generated package does not declare. Dropping it
        // silently ends in an undefined symbol at link time, so it is collected.
        unsupportedTargetDeps.push({
          target: t.name,
          dependsOn: name,
          kind: declaredKinds.get(name),
        });
      } else if (dep.byName != null) {
        // A `.byName` that is no target of this package resolves against the PRODUCTS of
        // the packages it declares, which a dumped manifest does not enumerate. Rendered
        // verbatim it resolves in the generated package exactly as it does in the
        // module's own manifest, and when it resolves to nothing SwiftPM says so by name.
        dependencies.push(
          typeof sibling === 'string' ? name : { byName: name, platforms: sibling.platforms }
        );
        spmProductNames.push(name);
      }
    }
    return {
      name: t.name,
      // An omitted `path:` is resolved against the filesystem by the emit layer.
      path: t.path ?? null,
      publicHeadersPath: t.publicHeadersPath ?? null,
      exclude: t.exclude ?? [],
      sources: t.sources ?? [],
      resources: t.resources ?? [],
      settings: t.settings ?? [],
      dependencies,
    };
  });

  const products = (pkg.products ?? [])
    .filter((p) => Object.keys(p.type ?? {})[0] === 'library')
    .map((p) => ({ name: p.name, targets: (p.targets ?? []).filter((n) => regularNames.has(n)) }))
    .filter((p) => p.targets.length);
  const iosDeploymentTarget =
    (pkg.platforms ?? []).find((p) => p.platformName === 'ios')?.version ?? null;
  return {
    name: pkg.name,
    iosDeploymentTarget,
    products,
    targets,
    packageDeps,
    spmProductNames: [...new Set(spmProductNames)],
    unsupportedTargetDeps,
    unsupportedPackageDeps,
  };
}

// ---------------------------------------------------------------------------
// Pure: render manifest strings
// ---------------------------------------------------------------------------

// Maps, not objects: a dumped manifest is untrusted input, and an inherited key like
// "constructor" would otherwise resolve to a function and render as garbage Swift.
const SWIFT_PLATFORM_CASES = new Map([
  ['ios', '.iOS'],
  ['macos', '.macOS'],
  ['maccatalyst', '.macCatalyst'],
  ['tvos', '.tvOS'],
  ['watchos', '.watchOS'],
  ['visionos', '.visionOS'],
  ['driverkit', '.driverKit'],
  ['linux', '.linux'],
  ['windows', '.windows'],
  ['android', '.android'],
  ['wasi', '.wasi'],
  ['openbsd', '.openbsd'],
]);

/**
 * The Swift cases for the platform names a condition lists. A name PackageDescription
 * does not declare is dropped while a supported one remains — the condition still
 * covers no more than the module declared. When none remains there is no safe
 * rendering: dropping the condition would apply the declaration everywhere, so this
 * throws instead of widening it.
 */
function swiftPlatformCases(names, context) {
  const declared = (names ?? []).map((p) => SWIFT_PLATFORM_CASES.get(p)).filter((p) => p != null);
  if (declared.length === 0 && (names ?? []).length > 0) {
    throw new Error(
      `Cannot generate a consumption Package.swift for ${context}: its platform condition names only ` +
        `${names.map((n) => `"${n}"`).join(', ')}, which PackageDescription 6.0 does not declare. Dropping ` +
        'the condition would apply the declaration on every platform, wider than the module declared. Add the ' +
        'platform to SWIFT_PLATFORM_CASES in expo/scripts/spm/manifests.js, or condition the declaration on a ' +
        'platform Swift Package Manager supports.'
    );
  }
  return declared;
}

/** SwiftPM allows only `platforms:` in a target-dependency condition. */
function renderPlatformCondition(platforms, context) {
  const cases = swiftPlatformCases(platforms, context);
  return cases.length ? `, condition: .when(platforms: [${cases.join(', ')}])` : '';
}

/**
 * One target dependency — a sibling target, a mirrored package's product, or a
 * `.byName` the module wrote against one of its packages — conditioned on platforms
 * when the module declared it so.
 */
function renderTargetDependency(dep) {
  if (typeof dep === 'string') return `"${escapeSwiftString(dep)}"`;
  if (dep.product != null) {
    const condition = renderPlatformCondition(dep.platforms, `the dependency on "${dep.product}"`);
    const name = escapeSwiftString(dep.product);
    return `.product(name: "${name}", package: "${escapeSwiftString(dep.package)}"${condition})`;
  }
  if (dep.byName != null) {
    const condition = renderPlatformCondition(dep.platforms, `the dependency on "${dep.byName}"`);
    const name = escapeSwiftString(dep.byName);
    return condition ? `.byName(name: "${name}"${condition})` : `"${name}"`;
  }
  const condition = renderPlatformCondition(dep.platforms, `the dependency on "${dep.name}"`);
  const name = escapeSwiftString(dep.name);
  return condition ? `.target(name: "${name}"${condition})` : `"${name}"`;
}

const RESOURCE_RULES = new Map([
  ['process', '.process'],
  ['copy', '.copy'],
  ['embedInCode', '.embedInCode'],
]);
const RESOURCE_LOCALIZATIONS = new Map([
  ['default', '.default'],
  ['base', '.base'],
]);

/**
 * A resource the module declared, as its `.process`/`.copy`/`.embedInCode` rule.
 * An unrecognized rule or localization throws: SwiftPM keeps adding both, and a
 * silently dropped resource means a library whose bundle is missing at runtime.
 */
function renderResource(resource, targetName) {
  const [rule, options] = Object.entries(resource.rule ?? {})[0] ?? [];
  const call = RESOURCE_RULES.get(rule);
  const localization =
    options?.localization != null ? RESOURCE_LOCALIZATIONS.get(options.localization) : null;
  if (call == null || (options?.localization != null && localization == null)) {
    throw new Error(
      `Cannot generate a consumption Package.swift for target "${targetName}": resource "${resource.path}" ` +
        `uses the unsupported rule \`${JSON.stringify(resource.rule)}\`. This plugin renders .process, .copy and ` +
        '.embedInCode with .default/.base localizations; a newer Swift Package Manager rule needs support added ' +
        'in expo/scripts/spm/manifests.js. Declare the resource with one of the supported rules meanwhile.'
    );
  }
  return localization != null
    ? `${call}("${resource.path}", localization: ${localization})`
    : `${call}("${resource.path}")`;
}

const SETTING_FAMILIES = [
  ['c', 'cSettings'],
  ['cxx', 'cxxSettings'],
  ['swift', 'swiftSettings'],
  ['linker', 'linkerSettings'],
];
const SETTING_TOOLS = new Set(SETTING_FAMILIES.map(([tool]) => tool));

function renderSettingCondition(condition, targetName) {
  const platforms = swiftPlatformCases(condition?.platformNames, `target "${targetName}"`);
  const clauses = [];
  if (platforms.length) clauses.push(`platforms: [${platforms.join(', ')}]`);
  if (condition?.config != null) clauses.push(`configuration: .${condition.config}`);
  return clauses.length ? `, .when(${clauses.join(', ')})` : '';
}

const SWIFT_LANGUAGE_MODES = new Map([
  ['4', '.v4'],
  ['4.2', '.v4_2'],
  ['5', '.v5'],
  ['6', '.v6'],
]);
const INTEROPERABILITY_MODES = new Map([
  ['C', '.C'],
  ['Cxx', '.Cxx'],
]);

function settingError(targetName, setting, explanation) {
  return new Error(
    `Cannot generate a consumption Package.swift for target "${targetName}": build setting ` +
      `\`${JSON.stringify(setting.kind)}\` ${explanation}`
  );
}

/**
 * One build setting as its PackageDescription call. An unrecognized kind throws for
 * the same reason an unrecognized resource rule does: a silently dropped setting
 * turns into a compile or link failure far from the manifest.
 */
function renderSetting(setting, targetName) {
  const [kind, args] = Object.entries(setting.kind ?? {})[0] ?? [];
  const value = args?._0;
  const when = renderSettingCondition(setting.condition, targetName);
  const malformed = (expected) =>
    settingError(
      targetName,
      setting,
      `carries ${JSON.stringify(value) ?? 'no value'} where ${expected} belongs. The dumped ` +
        'manifest is malformed; re-run `swift package dump-package` on the module to see what it emits.'
    );
  const quoted = (v) => {
    if (typeof v !== 'string' || v === '') throw malformed('a non-empty string');
    return `"${escapeSwiftString(v)}"`;
  };
  const text = () => {
    if (typeof value !== 'string' || value === '') throw malformed('a non-empty string');
    return value;
  };
  switch (kind) {
    case 'define': {
      const define = text();
      const separator = define.indexOf('=');
      if (separator < 0) return `.define(${quoted(define)}${when})`;
      const name = quoted(define.slice(0, separator));
      // A Swift define is a conditional-compilation flag: swiftc warns that flags have
      // no values and then `#if NAME` is false, so only the name survives.
      if (setting.tool === 'swift') return `.define(${name}${when})`;
      return `.define(${name}, to: ${quoted(define.slice(separator + 1))}${when})`;
    }
    case 'headerSearchPath':
      return `.headerSearchPath(${quoted(value)}${when})`;
    case 'unsafeFlags':
      if (!Array.isArray(value)) throw malformed('an array of flags');
      return `.unsafeFlags([${value.map(quoted).join(', ')}]${when})`;
    case 'linkedFramework':
      return `.linkedFramework(${quoted(value)}${when})`;
    case 'linkedLibrary':
      return `.linkedLibrary(${quoted(value)}${when})`;
    case 'enableUpcomingFeature':
      return `.enableUpcomingFeature(${quoted(value)}${when})`;
    case 'enableExperimentalFeature':
      return `.enableExperimentalFeature(${quoted(value)}${when})`;
    case 'swiftLanguageMode': {
      const mode = SWIFT_LANGUAGE_MODES.get(text());
      if (mode == null) {
        throw settingError(
          targetName,
          setting,
          `names the Swift language mode "${value}", which PackageDescription does not declare. ` +
            'The generated manifest would not compile. Declare the target with mode 4, 4.2, 5 or 6.'
        );
      }
      return `.swiftLanguageMode(${mode}${when})`;
    }
    case 'interoperabilityMode': {
      const mode = INTEROPERABILITY_MODES.get(text());
      if (mode == null) {
        throw settingError(
          targetName,
          setting,
          `names the interoperability mode "${value}", which PackageDescription does not declare. ` +
            'The generated manifest would not compile. Declare the target with mode C or Cxx.'
        );
      }
      return `.interoperabilityMode(${mode}${when})`;
    }
    default:
      if (kind == null) {
        throw settingError(
          targetName,
          setting,
          'carries no kind, so the renderer cannot tell what it declares. The dumped manifest is ' +
            'malformed; re-run `swift package dump-package` on the module to see what it emits.'
        );
      }
      throw settingError(
        targetName,
        setting,
        `uses the kind "${kind}", which this plugin's renderer does not support yet. Swift Package ` +
          'Manager keeps adding build settings, and rendering it needs a case added in ' +
          'expo/scripts/spm/manifests.js.'
      );
  }
}

/** SwiftPM's file-rule arguments, in `.target(…)` declaration order. Empty ones are omitted. */
function renderFileRules(target) {
  const list = (label, values) =>
    values.length ? `\n            ${label}: [${values.join(', ')}],` : '';
  const quoted = (paths) => (paths ?? []).map((p) => `"${p}"`);
  return (
    list('exclude', quoted(target.exclude)) +
    list('sources', quoted(target.sources)) +
    list(
      'resources',
      (target.resources ?? []).map((r) => renderResource(r, target.name))
    )
  );
}

/** Source-with-manifest: mirror the parsed targets, products and packages, inject the given deps. */
function renderSourceManifest(
  manifest,
  pkgDeps,
  injected,
  frameworkSearchPath,
  extraSwiftFlags = []
) {
  const targetsSwift = manifest.targets
    .map((t) => {
      if (t.path == null) {
        throw new Error(
          `Cannot generate a consumption Package.swift for "${manifest.name}": target "${t.name}" has no source path. ` +
            "Its path was neither declared in the module's manifest nor resolved on disk, so the generated target " +
            'would point at nothing. Resolve target paths with resolveTargetPaths before rendering.'
        );
      }
      const deps = [...t.dependencies.map(renderTargetDependency), ...injected];
      const depsSwift = deps.length
        ? `\n${deps.map((dep) => `                ${dep},`).join('\n')}\n            `
        : '';
      const headers = t.publicHeadersPath
        ? `\n            publicHeadersPath: "${t.publicHeadersPath}",`
        : '';
      return `        .target(
            name: "${t.name}",
            dependencies: [${depsSwift}],
            path: "root/${t.path}",${renderFileRules(t)}${headers}${renderTargetSettings(frameworkSearchPath, t.settings, t.name, extraSwiftFlags)}
        )`;
    })
    .join(',\n');

  const productsSwift = manifest.products
    .map(
      (p) =>
        `        .library(name: "${p.name}", targets: [${p.targets.map((n) => `"${n}"`).join(', ')}])`
    )
    .join(',\n');
  const declarations = [...pkgDeps, ...(manifest.packageDeps ?? []).map(dumpedPackageDeclaration)];
  const packageDepsSwift = declarations.length
    ? `\n${declarations.map((dep) => `        ${dep},`).join('\n')}\n    `
    : '';

  return `// swift-tools-version: 6.0
// AUTO-GENERATED by expo/scripts/spm/plugin.js — do not edit.
// Source consumption package for "${manifest.name}": mirrors the module's checked-in
// Package.swift targets and injects invariant React compile dependencies.
import PackageDescription

let package = Package(
    name: "${manifest.name}",
    platforms: ${renderPlatforms(manifest.iosDeploymentTarget ?? null)},
    products: [
${productsSwift}
    ],
    dependencies: [${packageDepsSwift}],
    targets: [
${targetsSwift}
    ],
    swiftLanguageModes: [.v5],
    cxxLanguageStandard: .cxx20
)
`;
}

// Apple requires this manifest in shipping apps; CocoaPods ships it as a resource bundle.
const PRIVACY_MANIFEST = 'PrivacyInfo.xcprivacy';

const SPM_VERSION_REQUIREMENTS = ['exact', 'from', 'branch', 'revision'];

/**
 * The requirement argument of a `.package(url:)` declaration, from the version an
 * spm.config.json entry declares. A version this cannot spell throws: the
 * alternative is a declaration SwiftPM fails to parse, far from the config.
 */
function spmVersionRequirement(version, url) {
  // Mirrors readSpmVersion in expo-modules-autolinking, which drops an ambiguous
  // version rather than publishing it: neither end may pick one of several.
  const declared =
    typeof version === 'object' && version !== null
      ? SPM_VERSION_REQUIREMENTS.filter((key) => key in version)
      : [];
  if (declared.length > 1) {
    throw new Error(
      `Cannot declare the Swift package "${url}": its spm.config.json entry names more than one version ` +
        `requirement (${declared.join(', ')}), and SwiftPM resolves a package at exactly one. Keep the ` +
        'requirement the package should resolve at and remove the others.'
    );
  }
  const value = declared.length === 1 ? version[declared[0]] : undefined;
  if (typeof value !== 'string') {
    throw new Error(
      `Cannot declare the Swift package "${url}": its spm.config.json entry names no version requirement ` +
        'this renderer supports, so SwiftPM has nothing to resolve the package at. Declare the entry with ' +
        'an exact, from, branch or revision version, written as a string.'
    );
  }
  return `${declared[0]}: "${escapeSwiftString(value)}"`;
}

/**
 * The identity SwiftPM resolves a package URL to: its last path component, without
 * trailing slashes or a `.git` suffix. It is the repository name, which differs
 * from the product where a repository ships one under another name, as
 * `libavif-Xcode` ships `libavif`.
 */
function spmPackageIdentity(pkg) {
  return pkg.url
    .replace(/\/+$/, '')
    .split('/')
    .pop()
    .replace(/\.git$/, '');
}

function spmPackageDeclaration(pkg) {
  return `.package(url: "${escapeSwiftString(pkg.url)}", ${spmVersionRequirement(pkg.version, pkg.url)})`;
}

/**
 * The same declaration for a package a checked-in manifest declares, which arrives in
 * the shape `swift package dump-package` prints. It is rendered apart from
 * `spmPackageDeclaration` because the two shapes differ: an spm.config.json entry has
 * a `from` requirement and no range, a dumped one has a range and no `from`.
 */
function dumpedPackageDeclaration({ url, requirement }) {
  const quoted = (value) => `"${escapeSwiftString(value)}"`;
  const pin =
    requirement.kind === 'range'
      ? `${quoted(requirement.lowerBound)}..<${quoted(requirement.upperBound)}`
      : `${requirement.kind}: ${quoted(requirement.value)}`;
  return `.package(url: ${quoted(url)}, ${pin})`;
}

function spmProductDependency(pkg) {
  return `.product(name: "${escapeSwiftString(pkg.productName)}", package: "${escapeSwiftString(spmPackageIdentity(pkg))}")`;
}

/**
 * Pure-Swift source: single Swift target over the module's `ios`/`apple` sources, on
 * the deployment floor the plugin read from the prebuilt-metadata document.
 */
function renderPureSwiftManifest(
  product,
  srcRel,
  pkgDeps,
  targetDeps,
  frameworkSearchPath,
  excludes = [],
  iosDeploymentTarget = null,
  hasPrivacyManifest = false,
  extraSwiftFlags = []
) {
  const packageDepsSwift = pkgDeps.length
    ? `\n${pkgDeps.map((dep) => `        ${dep},`).join('\n')}\n    `
    : '';
  const targetDepsSwift = targetDeps.length
    ? `\n${targetDeps.map((dep) => `                ${dep},`).join('\n')}\n            `
    : '';
  // SwiftPM resolves exclude paths against the target path, not the package root.
  const excludeSwift = excludes.length
    ? `\n            exclude: [${excludes.map((e) => `"${e}"`).join(', ')}],`
    : '';
  // `.copy`, not `.process`: Apple reads a privacy manifest by its exact name, and
  // .process may rename or transform what it puts in the bundle.
  const resourcesSwift = hasPrivacyManifest
    ? `\n            resources: [.copy("${PRIVACY_MANIFEST}")],`
    : '';
  return `// swift-tools-version: 6.0
// AUTO-GENERATED by expo/scripts/spm/plugin.js — do not edit.
// Pure-Swift source consumption package for "${product}".
import PackageDescription

let package = Package(
    name: "${product}",
    platforms: ${renderPlatforms(iosDeploymentTarget)},
    products: [
        .library(name: "${product}", targets: ["${product}"]),
    ],
    dependencies: [${packageDepsSwift}],
    targets: [
        .target(
            name: "${product}",
            dependencies: [${targetDepsSwift}],
            path: "root/${srcRel}",${excludeSwift}${resourcesSwift}${renderTargetSettings(frameworkSearchPath, [], product, extraSwiftFlags)}
        ),
    ],
    swiftLanguageModes: [.v5],
    cxxLanguageStandard: .cxx20
)
`;
}

function escapeSwiftString(value) {
  return value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

/**
 * A target's `*Settings:` arguments: Expo's binary-free interface tree first, then
 * whatever the module itself declared, in its own order.
 */
function renderTargetSettings(frameworkSearchPath, settings, targetName, extraSwiftFlags = []) {
  const unsafeFlags = (flags) =>
    `.unsafeFlags([${flags.map((f) => `"${escapeSwiftString(f)}"`).join(', ')}])`;
  const interfaceFlags = unsafeFlags(['-F', frameworkSearchPath]);
  // `-Xfrontend` is a Swift driver flag; clang rejects it, so it stays out of c/cxxSettings.
  const swiftInterfaceFlags = unsafeFlags(['-F', frameworkSearchPath, ...extraSwiftFlags]);
  for (const setting of settings ?? []) {
    if (!SETTING_TOOLS.has(setting.tool)) {
      throw new Error(
        `Cannot generate a consumption Package.swift for target "${targetName}": build setting tool ` +
          `"${setting.tool}" has no arguments to be rendered into. This plugin renders the c, cxx, swift ` +
          'and linker tools; a newer Swift Package Manager tool needs a family added in ' +
          'expo/scripts/spm/manifests.js.'
      );
    }
  }
  return SETTING_FAMILIES.map(([tool, label]) => {
    const own = (settings ?? [])
      .filter((s) => s.tool === tool)
      .map((s) => renderSetting(s, targetName));
    const injected = tool === 'swift' ? swiftInterfaceFlags : interfaceFlags;
    const values = tool === 'linker' ? own : [injected, ...own];
    return values.length ? `\n            ${label}: [${values.join(', ')}],` : '';
  }).join('');
}

/** Only iOS is mirrored: React Native's Swift Package Manager support is iOS-only. */
function renderPlatforms(iosDeploymentTarget) {
  return iosDeploymentTarget != null ? `[.iOS("${iosDeploymentTarget}")]` : '[.iOS(.v15)]';
}

/**
 * The higher of two iOS floors, or null when neither side declares one.
 *
 * CocoaPods raises every Expo pod to ExpoModulesCore's deployment target after
 * install (`reconcile_expo_module_deployment_targets`). Under SwiftPM the
 * generated manifest is the only place to do that, because importing a module
 * built for a higher floor than the importer is a compile error.
 */
function raiseFloor(declared, minimum) {
  if (declared == null) return minimum ?? null;
  if (minimum == null) return declared;
  const components = (version) => version.split('.').map(Number);
  const [left, right] = [components(declared), components(minimum)];
  for (let i = 0; i < Math.max(left.length, right.length); i++) {
    const delta = (left[i] ?? 0) - (right[i] ?? 0);
    if (delta !== 0) return delta > 0 ? declared : minimum;
  }
  return declared;
}

// ---------------------------------------------------------------------------
// I/O: emit a package dir (write manifest + `root` symlink) and return deps
// ---------------------------------------------------------------------------

// Where SwiftPM looks for a target's sources when the manifest omits `path:`.
const PREDEFINED_SOURCE_DIRS = ['Sources', 'Source', 'src', 'srcs'];

const SOURCE_FILE_RX = /\.(swift|m|mm|c|cc|cpp|cxx|s)$/i;

/** Whether `dir` contains a source file at any depth — SwiftPM's own condition. */
function holdsSourceFiles(dir) {
  let entries = [];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return false;
  }
  return entries.some((e) =>
    e.isDirectory() ? holdsSourceFiles(path.join(dir, e.name)) : SOURCE_FILE_RX.test(e.name)
  );
}

/**
 * Fill in each target's source path relative to the module root. A target that
 * omits `path:` is absent from the dump, so SwiftPM's own inference
 * (`<predefined source dir>/<target name>`) has to be redone here. Targets whose
 * directory does not exist are returned separately: they are reported, not rendered.
 *
 * A single-target package may also keep its sources directly in a predefined
 * directory, with no `<dir>/<target name>` level; SwiftPM only allows that when
 * the package has exactly one target, so the fallback is gated the same way.
 */
function resolveTargetPaths(targets, moduleRoot) {
  // Counting regular targets only matches SwiftPM: a lone regular target plus a
  // .testTarget still resolves to the bare directory.
  const singleTarget = targets.length === 1;
  const resolved = [];
  const unresolvedTargets = [];
  for (const target of targets) {
    if (target.path != null) {
      resolved.push(target);
      continue;
    }
    const inferred =
      PREDEFINED_SOURCE_DIRS.map((dir) => path.join(dir, target.name)).find((rel) =>
        fs.existsSync(path.join(moduleRoot, rel))
      ) ??
      (singleTarget
        ? PREDEFINED_SOURCE_DIRS.find((dir) => holdsSourceFiles(path.join(moduleRoot, dir)))
        : undefined);
    if (inferred == null) unresolvedTargets.push(target.name);
    else resolved.push({ ...target, path: inferred });
  }
  return { targets: resolved, unresolvedTargets };
}

/** Point a `root` symlink at the real module source so target `path:`s resolve to real files. */
function linkRoot(pkgDir, moduleRoot) {
  const rootLink = path.join(pkgDir, 'root');
  try {
    fs.rmSync(rootLink, { recursive: true, force: true });
  } catch {}
  fs.symlinkSync(moduleRoot, rootLink);
}

/**
 * React compile products are the exact invariant set supplied by RN's context.
 * Every Expo source target needs them: even a target that only imports
 * ExpoModulesCore loads its Clang module map, which declares `use React`.
 */
function sourceDependencies(react, codegenPkgPath) {
  const wireReact = react != null;
  return {
    targetDeps: wireReact ? reactProductDependencies(react) : [],
    pkgDeps: wireReact ? reactPackageDeclarations(react, codegenPkgPath) : [],
  };
}

/**
 * Option A: emit a CONSUMPTION Package.swift for a source module that ships a
 * checked-in Package.swift. Re-declares its library targets against the real source
 * (via a `root` symlink), injects RN's invariant React product set, and points
 * compilation at Expo's binary-free framework interface tree. RN owns the merge;
 * the checked-in manifest stays for standalone dev/describe.
 *
 * Returns `{ unsupportedTargetDeps }` when the manifest depends on a target the
 * generated package cannot declare, `{ unsupportedPackageDeps }` when it declares a
 * Swift package the generated package cannot declare, or `{ unresolvedTargets }` when
 * a target's sources cannot be located — the module is then skipped and diagnosed
 * rather than emitted broken.
 */
function emitSourceManifestPackage(
  moduleRoot,
  react,
  frameworkSearchPath,
  outDir,
  codegenPkgPath,
  minimumIosDeploymentTarget = null,
  macroFlags = []
) {
  const { unsupportedTargetDeps, unsupportedPackageDeps, ...dumped } = parseDumpedManifest(
    runDumpPackage(moduleRoot),
    injectedPackageNames(react)
  );
  if (unsupportedTargetDeps.length) return { unsupportedTargetDeps };
  if (unsupportedPackageDeps.length) return { unsupportedPackageDeps };
  const { targets, unresolvedTargets } = resolveTargetPaths(dumped.targets, moduleRoot);
  if (unresolvedTargets.length) return { unresolvedTargets };
  const manifest = {
    ...dumped,
    targets,
    iosDeploymentTarget: raiseFloor(dumped.iosDeploymentTarget, minimumIosDeploymentTarget),
  };
  const pkgDir = path.join(outDir, 'expo-source', manifest.name);
  fs.mkdirSync(pkgDir, { recursive: true });
  linkRoot(pkgDir, moduleRoot);

  const { targetDeps, pkgDeps } = sourceDependencies(react, codegenPkgPath);
  fs.writeFileSync(
    path.join(pkgDir, 'Package.swift'),
    renderSourceManifest(manifest, pkgDeps, targetDeps, frameworkSearchPath, macroFlags)
  );

  return {
    packageDep: { name: manifest.name, path: pkgDir },
    productDeps: manifest.products.map((p) => ({ name: p.name, package: manifest.name })),
    spmProductNames: manifest.spmProductNames,
  };
}

/**
 * Emit a source consumption package for a module WITHOUT a checked-in Package.swift,
 * from its resolved descriptor. Pure-Swift modules only (single Swift target over the
 * module's `ios` sources). It compiles against Expo's invariant interface tree,
 * plus RN's invariant React products.
 */
function emitPureSwiftSourcePackage(
  moduleRoot,
  product,
  react,
  frameworkSearchPath,
  outDir,
  codegenPkgPath,
  iosDeploymentTarget = null,
  macroFlags = [],
  spmPackages = []
) {
  const srcDir = ['ios', 'apple']
    .map((s) => path.join(moduleRoot, s))
    .find((d) => fs.existsSync(d));
  if (srcDir == null) return null;
  const srcRel = path.relative(moduleRoot, srcDir); // e.g. "ios"
  const pkgDir = path.join(outDir, 'expo-source', product);
  fs.mkdirSync(pkgDir, { recursive: true });
  linkRoot(pkgDir, moduleRoot);

  const { targetDeps, pkgDeps } = sourceDependencies(react, codegenPkgPath);
  fs.writeFileSync(
    path.join(pkgDir, 'Package.swift'),
    renderPureSwiftManifest(
      product,
      srcRel,
      [...pkgDeps, ...spmPackages.map((pkg) => spmPackageDeclaration(pkg))],
      [...targetDeps, ...spmPackages.map((pkg) => spmProductDependency(pkg))],
      frameworkSearchPath,
      collectIgnoredDirs(srcDir),
      iosDeploymentTarget,
      fs.existsSync(path.join(srcDir, PRIVACY_MANIFEST)),
      macroFlags
    )
  );

  return {
    packageDep: { name: product, path: pkgDir },
    productDep: { name: product, package: product },
  };
}

module.exports = {
  parseDumpedManifest,
  resolveTargetPaths,
  renderSourceManifest,
  renderPureSwiftManifest,
  spmPackageIdentity,
  spmPackageDeclaration,
  spmProductDependency,
  raiseFloor,
  emitSourceManifestPackage,
  emitPureSwiftSourcePackage,
};
